def main():
    metro_file = r"d:\drl_project\data\chennai_metro.json"
    with open(metro_file, "r", encoding="utf-8") as f:
        metro_data = json.load(f)
        
    all_stations = []
    for line in metro_data["lines"]:
        for st in line["stations"]:
            all_stations.append({
                "name": st["name"],
                "lat": st["lat"],
                "lon": st["lon"],
                "line": line["line_name"]
            })

    # Enrich with Metro and Accessibility
    for p in MASTER_PLACES:
        nearest_st = min(all_stations, key=lambda s: haversine(p["lat"], p["lon"], s["lat"], s["lon"]))
        dist = round(haversine(p["lat"], p["lon"], nearest_st["lat"], nearest_st["lon"]), 2)
        
        p["latitude"] = p["lat"]
        p["longitude"] = p["lon"]
        p["recommended_duration_hours"] = p["dur"]
        p["open_time"] = p["open"]
        p["close_time"] = p["close"]
        p["entry_fee_inr"] = p["fee"]
        p["best_time_of_day"] = p["tod"]
        p["description"] = p["desc"]
        p["famous_for"] = p["famous"]
        p["nearest_metro_station"] = nearest_st["name"]
        p["metro_line"] = nearest_st["line"]
        p["distance_to_metro_km"] = dist
        p["metro_accessible"] = bool(dist <= 3.0)
        p["elderly_friendly"] = bool(p["category"] in ["Temples & Spiritual", "Parks & Nature", "Food, Messes & Cafes", "Shopping & Markets"] and dist <= 3.5)
        p["wheelchair_accessible"] = bool(p["category"] in ["Shopping & Markets", "Museums & Arts", "Parks & Nature"])
        p["tags"] = [p["category"].lower(), p["zone"].lower(), p["area"].lower()]

    out_dir = r"d:\drl_project\tourist_places"
    json_path = os.path.join(out_dir, "chennai_places.json")
    csv_path = os.path.join(out_dir, "chennai_places.csv")
    
    with open(json_path, "w", encoding="utf-8") as f:
        json.dump(MASTER_PLACES, f, indent=2, ensure_ascii=False)
        
    df = pd.DataFrame(MASTER_PLACES)
    df.to_csv(csv_path, index=False, encoding="utf-8")
    print(f"Generated {len(MASTER_PLACES)} verified, exhaustive Chennai Places with shopping malls, beaches, food, and metro links!")

if __name__ == "__main__":
    main()
